      >
        {!imgError ? (
          <Image
            source={{ uri: iconUrl }}
            style={styles.bgImage}
            resizeMode="cover"
            onError={() => setImgError(true)}
          />
        ) : (
          <View style={[styles.bgImage, styles.bgFallback]} />
        )}

        <LinearGradient
          colors={['transparent', 'rgba(0,0,0,0.15)', 'rgba(0,0,0,0.72)']}
          locations={[0, 0.4, 1]}
          style={styles.gradient}
        />

        {isSummited && (
